        return {
            "status_code": 200, 
            "results": {
                "function_name": "HT_TRENDMODE",
                "p_symbol": p_symbol,
                "p_interval": p_interval,
                "p_series_type": p_series_type,
                "p_format": p_format,
                "p_outputsize": p_outputsize
            }
        }

